settings.custom_liquid:
{%- liquid
  assign mf_vd = product.metafields.custom.volume_discounts
  assign vd = '{"tiers":[]}'

  if mf_vd != blank and mf_vd.value != blank
    if mf_vd.type == 'json'
      assign vd = mf_vd.value | json
    else
      assign vd = mf_vd.value | strip
    endif
  endif

  assign v = product.selected_or_first_available_variant
  assign show_price = false
  assign initial_incl_cents = 0
  assign initial_excl_cents = 0

  if v and v.price > 1
    assign show_price = true
    assign initial_incl_cents = v.price
    assign initial_excl_cents = v.price | times: 100.0 | divided_by: 121.0 | round
  endif
-%}

<div
  data-rt-product-ui
  data-rt-section-id="{{ section.id }}"
  data-rt-vat-rate="0.21"
  data-rt-price-includes-vat="true"
  data-rt-hide-base-unit-cents-lte="1"
  data-rt-money-format="{{ shop.money_format | escape }}"
  data-rt-locale="{{ request.locale.iso_code }}"
  data-rt-currency="{{ cart.currency.iso_code | default: shop.currency }}"
>
  <style>
    :root{
      --rt-blue: #003878;
      --rt-price: #FF7300;
      --rt-green: #74C200;
      --rt-radius: 8px;
    }

    [data-rt-price-box]{
      margin: 0;
      padding: 0;
      border: 0;
      border-radius: var(--rt-radius);
      background: transparent;
      max-width: 520px;
      min-height: 0;
    }

    [data-rt-price-box][hidden]{
      display: none !important;
    }

    [data-rt-price-excl]{
      color: var(--rt-price);
      font-weight: 800;
      font-size: 24px;
      line-height: 1.05;
      margin: 0;
      padding: 0;
    }

    [data-rt-price-incl]{
      color: var(--rt-blue);
      font-weight: 600;
      font-size: 14px;
      line-height: 1.1;
      opacity: .9;
      margin: 6px 0 0;
      padding: 0;
    }

    [data-rt-price-save]{
      color: var(--rt-green);
      font-weight: 700;
      font-size: 14px;
      line-height: 1.2;
      margin: 0;
      padding: 0;
      min-height: 0;
    }

    [data-rt-price-save]:empty{
      display: none;
    }

    [data-rt-price-save]:not(:empty){
      margin-top: 8px;
    }

    @media (max-width: 767px){
      [data-rt-price-box]{
        max-width: 100%;
      }

      [data-rt-price-excl]{
        font-size: 22px;
      }
    }
  </style>

  <div data-rt-price-box{% unless show_price %} hidden{% endunless %}>
    <div data-rt-price-excl>
      {%- if show_price -%}
        {{ initial_excl_cents | money }} (excl. BTW)
      {%- endif -%}
    </div>

    <div data-rt-price-incl>
      {%- if show_price -%}
        {{ initial_incl_cents | money }} (incl. BTW)
      {%- endif -%}
    </div>

    <div data-rt-price-save></div>
  </div>

  <script type="application/json" data-rt-product-tiers>{{ vd }}</script>

  <script type="application/json" data-rt-product-variant-prices>
    [
      {%- for v in product.variants -%}
        {"id":{{ v.id }},"price":{{ v.price }}}{%- unless forloop.last -%},{%- endunless -%}
      {%- endfor -%}
    ]
  </script>
</div>

{%- assign bc_col = product.metafields.custom.collectie.value -%}

{%- if bc_col != blank -%}
  <div class="rt-bc-outer page-width">
    <nav class="rt-bc" aria-label="Breadcrumb">
      <ol class="rt-bc__list" role="list">
        <li class="rt-bc__item">
          <a class="rt-bc__link" href="{{ bc_col.url }}">{{ bc_col.title }}</a>
        </li>
        <li class="rt-bc__sep" aria-hidden="true">/</li>
        <li class="rt-bc__item">
          <span class="rt-bc__current" aria-current="page">{{ product.title }}</span>
        </li>
      </ol>
    </nav>
  </div>

  <style>
    .rt-bc-outer{
      width: 100% !important;
      max-width: var(--page-width, 1200px);
      margin: 0 auto !important;

      background: #FFF */
      padding: 12px 12px 12px 16px !important;

      border-radius: 0 !important;

      text-align: left !important;
      justify-self: start !important;
      align-self: start !important;
      place-self: start !important;
    }

    .rt-bc{
      margin: 0 !important;
      padding: 0 !important;
      width: 100% !important;
      text-align: left !important;
      font-family: inherit;
      font-size: 14px;
      font-weight: 500;
      line-height: 1.2;
      color: #003878;
    }

    .rt-bc__list{
      display: flex;
      justify-content: flex-start !important;
      align-items: center;
      gap: 8px;
      margin: 0 !important;
      padding: 0 !important;
      list-style: none !important;
      width: 100% !important;
      flex-wrap: wrap;
    }

    .rt-bc__link{
      color: #003878;
      text-decoration: none;
      transition: color .15s ease, text-decoration-color .15s ease;
    }
    .rt-bc__link:hover{
      color: #FF7300;
      text-decoration: underline;
      text-decoration-color: #FF7300;
    }

    /* ✅ ook blauw */
    .rt-bc__sep{
      color: #003878;
    }

    /* ✅ ook blauw */
    .rt-bc__current{
      color: #003878;
      font-size: 14px;
      font-weight: 500;
    }

@media (max-width: 749px){
  .rt-bc-outer{
    /* full-bleed op mobiel (edge-to-edge) */
    width: 100vw !important;
    max-width: none !important;

    /* breek uit de page-width container */
    margin-left: calc(50% - 50vw) !important;
    margin-right: calc(50% - 50vw) !important;

    /* jouw padding */
    padding: 12px 10px 12px 12px !important;
  }
}

  </style>
{%- endif -%}

{%- liquid
  assign threshold_eur = 49
  assign threshold_cents = threshold_eur | times: 100
  assign qualifies_free_shipping = false

  if product.selected_or_first_available_variant and product.selected_or_first_available_variant.price >= threshold_cents
    assign qualifies_free_shipping = true
  endif

  assign has_out_of_stock_variant = false

  for variant in product.variants
    assign variant_stock = variant.inventory_quantity | default: 0

    if variant_stock <= 0
      assign has_out_of_stock_variant = true
    endif
  endfor

  assign now_ts = 'now' | date: '%s'
  assign current_hour = 'now' | date: '%H' | plus: 0
  assign current_wday = 'now' | date: '%w' | plus: 0

  assign tomorrow_ts = now_ts | plus: 86400
  assign tomorrow_wday = tomorrow_ts | date: '%w'

  assign tomorrow_name = ''
  case tomorrow_wday
    when '1'
      assign tomorrow_name = 'MAANDAG'
    when '2'
      assign tomorrow_name = 'DINSDAG'
    when '3'
      assign tomorrow_name = 'WOENSDAG'
    when '4'
      assign tomorrow_name = 'DONDERDAG'
    when '5'
      assign tomorrow_name = 'VRIJDAG'
    when '6'
      assign tomorrow_name = 'ZATERDAG'
    when '0'
      assign tomorrow_name = 'ZONDAG'
  endcase

  assign delivery_text = '1–3 werkdagen'

  if has_out_of_stock_variant
    assign delivery_text = '2–7 werkdagen'
  else
    if current_wday >= 1 and current_wday <= 5 and current_hour < 14
      assign delivery_text = tomorrow_name | append: ' (1-3 werkdagen)'
    else
      assign delivery_text = '1–3 werkdagen'
    endif
  endif
-%}

<div class="rt-shipfree-static" aria-label="Leveringsinformatie">
  <div class="rt-shipfree-static__line rt-shipfree-static__line--main">
    {%- if qualifies_free_shipping -%}
      <span class="rt-shipfree-static__free">Gratis levering</span>
    {%- else -%}
      Gratis levering vanaf €{{ threshold_eur }}
    {%- endif -%}
  </div>

  <div class="rt-shipfree-static__line rt-shipfree-static__line--sub">
    Verwachte levertijd: {{ delivery_text }}
  </div>
</div>

<style>
  .rt-shipfree-static {
    display: inline-flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
    width: fit-content;
    max-width: 100%;
    margin: 10px 0;
    padding: 8px 10px;
    border-radius: 8px;
    background: #EBF4FF;
    color: #002B5C;
    font-family: Overpass, sans-serif;
    line-height: 1.2;
  }

  .rt-shipfree-static__line--main {
    font-size: 14px;
    font-weight: 600;
  }

  .rt-shipfree-static__line--sub {
    font-size: 14px;
    font-weight: 500;
  }

  .rt-shipfree-static__free {
    color: #74C200;
    font-weight: 700;
  }

  @media (max-width: 480px) {
    .rt-shipfree-static {
      width: 100%;
    }
  }
</style>

{%- assign mf_vd = product.metafields.custom.volume_discounts -%}
{%- assign vd = '' -%}
{%- assign has_tiers = false -%}

{%- if mf_vd != blank and mf_vd.value != blank -%}
  {%- if mf_vd.type == 'json' -%}
    {%- assign vd = mf_vd.value | json -%}
    {%- assign tiers_arr = mf_vd.value.tiers -%}
    {%- if tiers_arr != blank and tiers_arr.size > 0 -%}
      {%- assign has_tiers = true -%}
    {%- endif -%}
  {%- else -%}
    {%- assign vd = mf_vd.value | default: '' | strip -%}
    {%- if vd != blank -%}
      {%- assign has_tiers = true -%}
    {%- endif -%}
  {%- endif -%}
{%- endif -%}

{%- if has_tiers -%}
  <div
    data-rt-product-ui
    data-rt-discount-ui
    data-rt-section-id="{{ section.id }}"
    data-rt-vat-rate="0.21"
    data-rt-price-includes-vat="true"
    data-rt-hide-base-unit-cents-lte="1"
    data-rt-money-format="{{ shop.money_format | escape }}"
    data-rt-locale="{{ request.locale.iso_code }}"
    data-rt-currency="{{ cart.currency.iso_code | default: shop.currency }}"
  >
    <style>
      [data-rt-discount-ui]{
        --rt-blue: #003878;
        --rt-orange: #FF7300;
        --rt-green: #74C200;
        --rt-grey: #EDF0F2;
        --rt-border: rgba(160,178,201,.55);
        --rt-text: rgba(0,0,0,.78);
      }

      [data-rt-discount-ui] [data-rt-discount-wrap][hidden]{
        display: none !important;
      }

      [data-rt-discount-ui] .discount-table{
        width: 100%;
        max-width: 720px;
        margin-top: 0;
        border-collapse: separate;
        border-spacing: 0;
        table-layout: fixed;
        border: 1px solid var(--rt-border);
        overflow: hidden;
        background: #fff;
      }

      @media (max-width: 767px){
        [data-rt-discount-ui] .discount-table{
          max-width: 100%;
        }
      }

      [data-rt-discount-ui] .discount-table th{
        background: #fff;
        color: var(--rt-blue);
        font-weight: 700;
        padding: 10px 8px;
        text-align: center;
        vertical-align: middle;
        border-bottom: 1px solid var(--rt-border);
        font-size: 14px;
      }

      [data-rt-discount-ui] .discount-table th .subtext{
        display: block;
        margin-top: 2px;
        font-size: 12px;
        font-weight: 500;
        color: var(--rt-text);
      }

      [data-rt-discount-ui] .discount-table td{
        padding: 10px 8px;
        text-align: center;
        vertical-align: middle;
        font-size: 13px;
        font-weight: 500;
        color: var(--rt-text);
        border-bottom: 1px solid var(--rt-border);
        background: #fff;
      }

      [data-rt-discount-ui] .discount-table tbody tr:nth-child(even) td{
        background: var(--rt-grey);
      }

      [data-rt-discount-ui] .discount-table td.korting{
        color: var(--rt-green);
        font-weight: 700;
      }

      [data-rt-discount-ui] .discount-table tbody tr[data-min-qty]{
        cursor: pointer;
      }

      @media (hover: hover) and (pointer: fine){
        [data-rt-discount-ui] .discount-table tbody tr[data-min-qty]:not(.active-tier):hover td{
          color: var(--rt-orange);
        }

        [data-rt-discount-ui] .discount-table tbody tr[data-min-qty]:not(.active-tier):hover td.korting{
          color: var(--rt-green);
        }
      }

      [data-rt-discount-ui] .discount-table tbody tr.active-tier td{
        font-weight: 700;
        box-shadow:
          inset 0 2px 0 var(--rt-blue),
          inset 0 -2px 0 var(--rt-blue);
      }

      [data-rt-discount-ui] .discount-table tbody tr.active-tier td:first-child{
        box-shadow:
          inset 2px 0 0 var(--rt-blue),
          inset 0 2px 0 var(--rt-blue),
          inset 0 -2px 0 var(--rt-blue);
      }

      [data-rt-discount-ui] .discount-table tbody tr.active-tier td:last-child{
        box-shadow:
          inset -2px 0 0 var(--rt-blue),
          inset 0 2px 0 var(--rt-blue),
          inset 0 -2px 0 var(--rt-blue);
      }

      [data-rt-discount-ui] .discount-table tbody tr:last-child td{
        border-bottom: none;
      }

      [data-rt-discount-ui] .discount-table tbody tr.active-tier td.korting{
        font-weight: 700;
      }
    </style>

    <div data-rt-discount-wrap hidden>
      <div data-rt-discount-table></div>
    </div>

    <script type="application/json" data-rt-product-tiers>{{ vd }}</script>

    <script type="application/json" data-rt-product-variant-prices>
      [
        {%- for v in product.variants -%}
          {"id":{{ v.id }},"price":{{ v.price }}}{%- unless forloop.last -%},{%- endunless -%}
        {%- endfor -%}
      ]
    </script>
  </div>
{%- endif -%}
